import type { Address } from "@/types/address";
import type { Claim } from "@LAF/Services/UnionService";
import type {
  PounderId,
  Pounder,
  PounderState,
  Vault,
  ZapDeposit,
  ZapsFactories,
} from "@Pounders/Models";
import { getVirtualPrice } from "@Pounders/Models";

type PounderStore = {
  pounder: Pounder<Vault>;
  state: PounderState;
  zapsFactories: ZapsFactories;
};

// eslint-disable-next-line max-lines-per-function
export const useUnionStore = defineStore("unionStore", () => {
  const pounders = reactive<Record<PounderId, PounderStore | null>>({
    ucrv: null,
    ucrv2: null,
    ufxs: null,
    uprisma: null,
    ucvx: null,
    ubal: null,
    ufxslp: null,
  });

  const claims = reactive<Record<PounderId, Claim | undefined>>({
    ucrv: undefined,
    ucrv2: undefined,
    ufxs: undefined,
    uprisma: undefined,
    ucvx: undefined,
    ubal: undefined,
    ufxslp: undefined,
  });

  function getPounder(pounderId: PounderId) {
    const pounder = pounders[pounderId];

    return {
      pounder: pounder?.pounder,
      state: pounder?.state,
      zapsFactories: pounder?.zapsFactories,
    };
  }

  async function updatePounder(pounderId: PounderId) {
    const { pounder, state } = getPounder(pounderId);
    if (!pounder || !state) {
      return;
    }

    const [
      priceUnderlying,
      apy,
      decimalsWithdraw,
      symbolWithdraw,
      tvl,
      priceShare,
      oraclePrice,
    ] = await Promise.all([
      pounder.getPriceUnderlying(),
      pounder.getApy(),
      pounder.contract.read.decimals(),
      pounder.contract.read.symbol(),
      pounder.contract.read.totalSupply(),
      getVirtualPrice(pounder.contract),
      pounder.lp?.getOraclePrice() ?? 1,
    ]);

    state.priceUnderlying = priceUnderlying;
    state.apy = apy;
    state.symbolLpPrimary = pounder.lp?.symbolPrimary ?? "";
    state.decimalsWithdraw = BigInt(decimalsWithdraw);
    state.symbolWithdraw = symbolWithdraw;
    state.tvl = tvl;
    state.priceShare = priceShare;
    state.oraclePrice = oraclePrice;
  }

  async function updateBalances(pounderId: PounderId, wallet?: Address) {
    const { pounder, state } = getPounder(pounderId);

    if (state) {
      if (wallet && pounder) {
        state.balanceWithdraw = await pounder.contract.read.balanceOf([wallet]);
      } else {
        state.balanceWithdraw = undefined;
      }
    }
  }

  async function updateZapDeposit(
    pounderId: PounderId,
    zapDeposit: ZapDeposit | undefined
  ) {
    const { state } = getPounder(pounderId);

    if (state && zapDeposit) {
      state.symbolDeposit = zapDeposit.depositSymbol;
      state.balanceDeposit = await zapDeposit.depositBalance();
      state.decimalsDeposit = (await zapDeposit.depositDecimals()) ?? 18n;
    }
  }

  function updateClaim(pounderId: PounderId, claim?: Claim) {
    const { state } = getPounder(pounderId);
    if (!state) {
      return;
    }

    state.balanceUnclaimed = BigInt(claim ? claim.amount : 0);
  }

  return {
    pounders,
    claims,
    getPounder,
    updatePounder,
    updateBalances,
    updateZapDeposit,
    updateClaim,
  };
});

import { abi as abiVault } from "@/ABI/Union/UnionVault";
import logoCRV from "@/Assets/Icons/Tokens/crv.svg";
import type { Address } from "@/types/address";
import { maxApprove } from "@/Utils/Wallet";
import type { ZapDeposit } from "@Pounders/Models";
import { getBalance, getDecimals } from "@Pounders/Zaps/Helpers";

export function uCrvDepositZaps(
  getConfig: () => Config,
  getAddress: () => Address | undefined,
  getInput: () => bigint | undefined
): ZapDeposit[] {
  const deposit = async () => {
    const config = getConfig();
    const address = getAddress();
    const input = getInput();

    if (!address || !input) {
      throw new Error("Unable to construct deposit zaps");
    }

    await maxApprove(
      config,
      CvxCrvAddress,
      address,
      UnionCrvVaultAddress,
      input
    );

    const args = [address, input] as const;
    const hash = await writeContract(config, {
      abi: abiVault,
      address: UnionCrvVaultAddress,
      functionName: "deposit",
      args,
    });

    return waitForTransactionReceipt(config, { hash });
  };

  // Zaps
  const cvxCRV: ZapDeposit = {
    logo: logoCRV,
    label: "cvxCRV",
    zap: () => deposit(),
    depositSymbol: "cvxCRV",
    depositBalance: () => getBalance(getConfig, getAddress, CvxCrvAddress),
    depositDecimals: () => getDecimals(getConfig, CvxCrvAddress),
  };

  const options = [cvxCRV];

  return options;
}

import { abi as abiVault } from "@/ABI/Union/UnionVault";
import logoCRV from "@/Assets/Icons/Tokens/crv.svg";
import type { Address } from "@/types/address";
import type { ZapWithdraw } from "@Pounders/Models";

export function uCrvWithdrawZaps(
  getConfig: () => Config,
  getAddress: () => Address | undefined,
  getInput: () => bigint | undefined
): ZapWithdraw[] {
  const withdraw = async () => {
    const config = getConfig();
    const address = getAddress();
    const input = getInput();

    if (!address || !input) {
      throw new Error("Unable to construct withdraw zaps");
    }

    const args = [address, input] as const;
    const hash = await writeContract(config, {
      abi: abiVault,
      address: UnionCrvVaultAddress,
      functionName: "withdraw",
      args,
    });

    return waitForTransactionReceipt(config, { hash });
  };

  // Zaps
  const cvxCRV: ZapWithdraw = {
    logo: logoCRV,
    label: "cvxCRV",
    withdrawSymbol: "cvxCRV",
    withdrawDecimals: () => Promise.resolve(18n),
    zap: () => withdraw(),
  };

  const options = [cvxCRV];

  return options;
}
